<?php require_once __DIR__.'/../includes/layout.php'; $u=require_login(); $msg=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf(); $photo=null; if(!empty($_FILES['photo']['tmp_name'])){ $ext=strtolower(pathinfo($_FILES['photo']['name'],PATHINFO_EXTENSION)); if(in_array($ext,['jpg','jpeg','png','webp'],true)){ $photo='uploads/photos/user_'.$u['id'].'_'.time().'.'.$ext; move_uploaded_file($_FILES['photo']['tmp_name'],__DIR__.'/../'.$photo); }} $sql='UPDATE user_profiles SET full_name=?,address=?,place=?,district=?,state=?,country=?,living_place=?,working_place=?,certificate_number=?,msr_number=?,phone=?'.($photo?',photo=?':'').' WHERE user_id=?'; $args=[$_POST['full_name'],$_POST['address'],$_POST['place'],$_POST['district'],$_POST['state'],$_POST['country'],$_POST['living_place'],$_POST['working_place'],$_POST['certificate_number'],$_POST['msr_number'],$_POST['phone']]; if($photo)$args[]=$photo; $args[]=$u['id']; db()->prepare($sql)->execute($args); audit('profile_update','users',$u['id']); $msg='Profile updated.';} $s=db()->prepare('SELECT * FROM user_profiles WHERE user_id=?');$s->execute([$u['id']]);$p=$s->fetch(); dashboard_header('Account Settings'); ?><div class="glass-card p-4"><h4><?=e($msg)?></h4><form method="post" enctype="multipart/form-data" class="row g-3"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><?php foreach(['full_name','address','place','district','state','country','living_place','working_place','certificate_number','msr_number','phone'] as $f):?><div class="col-md-6 form-floating"><input class="form-control" name="<?=$f?>" value="<?=e($p[$f]??'')?>" placeholder="<?=$f?>"><label><?=ucwords(str_replace('_',' ',$f))?></label></div><?php endforeach;?><div class="col-12"><label>Drag/drop or choose profile photo (crop/resize before upload as needed)</label><input type="file" name="photo" class="form-control" accept="image/*"></div><button class="btn btn-premium">Save Settings</button></form></div><?php dashboard_footer(); ?>
